function SchemasAdmin() {
  const qc = useQueryClient();
  const { site } = useSite();
  const q = useQuery({
    queryKey: ["schemas", site?.site_id],
    queryFn: ({ signal }) =>
      get<Schema[]>(
        `/api/v1/event-definitions?site_id=${site?.site_id || ""}`,
        { signal },
      ),
  });
  const [form, setForm] = useState({
    name: "",
    description: "",
    validation_mode: "warn",
    conversion: false,
    schemaText: '{"properties": {}}',
  });
  const save = useMutation({
    meta: { successMessage: "저장했습니다." },
    mutationFn: () =>
      post("/api/v1/event-definitions", {
        site_id: site?.site_id,
        ...form,
        schema: JSON.parse(form.schemaText),
      }),
    onSuccess: () => {
